'use strict';
// Emblems record a weapon family for future Buff/Passive selection; never grant Active skills.
function emblemIcon(weapon='sword'){const inside=weaponIcon(weapon).replace(/^<svg[^>]*>|<\/svg>$/g,'');return '<svg class="emblem-symbol" viewBox="0 0 32 32" aria-hidden="true"><path d="M16 1 29 8v16l-13 7L3 24V8Z" fill="#243e36" stroke="currentColor" stroke-width="2"/><path d="M16 4 26 10v12l-10 6L6 22V10Z" fill="none" stroke="currentColor" opacity=".4"/><g transform="translate(6 6) scale(.83)">'+inside+'</g></svg>'}
function equippedEmblemType(p=player){const item=p.loot.gear.find(g=>g.id===p.loot.equipped.emblem&&g.slot==='emblem');return item?.emblemWeapon||null}
function migrateEmblemLoot(raw){if(!raw||typeof raw!=='object'||Array.isArray(raw))return raw;const data=structuredClone(raw);if(data.boxes&&data.boxes.emblemMaterial===undefined)data.boxes.emblemMaterial=0;if(data.boxLevels&&data.boxLevels.emblemMaterial===undefined)data.boxLevels.emblemMaterial={};if(data.boxes&&data.boxes.emblem===undefined)data.boxes.emblem=0;if(data.boxLevels&&data.boxLevels.emblem===undefined)data.boxLevels.emblem={};if(Array.isArray(data.gear))for(const g of data.gear){if(!g||g.slot!=='secondary')continue;let type=g.weapon||'sword';if(type==='axe')type='hammer';if(type==='claw')type='fist';g.slot='emblem';g.emblemWeapon=type;g.weapon=null;g.name='Emblem '+(WEAPON_NAMES[type]||type);g.atk=g.def=g.hp=g.mp=0}if(data.equipped?.secondary){if(data.equipped.emblem&&data.equipped.emblem!==data.equipped.secondary)throw Error('ช่อง Emblem ซ้ำ');data.equipped.emblem=data.equipped.secondary;delete data.equipped.secondary}return data}
function generateEmblem(stage,level){const types=Object.keys(WEAPON_NAMES),emblemWeapon=types[Math.floor(Math.random()*types.length)],rarity=rarityRoll(),quality=LOOT_RARITIES[rarity],count=quality.min+Math.floor(Math.random()*(quality.max-quality.min+1)),pool=Object.keys(BONUS_NAMES),scale=Math.max(0,Math.floor(level/10)),bonuses=[];for(let i=0;i<count;i++){const key=pool.splice(Math.floor(Math.random()*pool.length),1)[0];bonuses.push({key,value:['hp','mp'].includes(key)?10+scale*5:1+Math.floor(Math.random()*3)+scale})}return {id:crypto.randomUUID(),name:'Emblem '+WEAPON_NAMES[emblemWeapon],slot:'emblem',weapon:null,emblemWeapon,stage,level,rarity,atk:0,def:0,hp:0,mp:0,bonuses}}
function emblemDescription(g){return 'Emblem · '+WEAPON_NAMES[g.emblemWeapon]+' · Lv.'+g.level+'\n'+LOOT_RARITIES[g.rarity].name+' · สวมช่อง Emblem ได้ทุกอาชีพ\nระบุประเภทอาวุธสำหรับ Buff/Passive ข้ามอาวุธ\n'+((g.bonuses||[]).length?'Option\n'+g.bonuses.map(weaponOptionText).join('\n'):'ไม่มี Option')}
function emblemStatusCard(g){g=enchantedGear(g);const card=document.createElement('div');card.className='weapon-status-card emblem-status-card';const heading=document.createElement('div');heading.className='weapon-status-emblem';heading.innerHTML=emblemIcon(g.emblemWeapon);const quality=document.createElement('span');quality.textContent=LOOT_RARITIES[g.rarity].name;quality.style.color=LOOT_RARITIES[g.rarity].color;heading.append(quality);card.append(heading);const rows=document.createElement('dl');for(const [label,value]of [['ประเภท','Emblem '+WEAPON_NAMES[g.emblemWeapon]],['เลเวล','Lv.'+g.level],['ช่อง','Emblem'],['ตีบวก','+'+enchantLevel(g)],['อาชีพ','ทุกอาชีพ']]){const term=document.createElement('dt'),description=document.createElement('dd');term.textContent=label;description.textContent=value;rows.append(term,description)}card.append(rows);const note=document.createElement('p');note.textContent='ใช้ Buff/Passive ของประเภทนี้ได้';card.append(note);const options=document.createElement('section');options.className='weapon-status-options';const title=document.createElement('strong');title.textContent='Option';options.append(title);for(const text of g.bonuses.length?g.bonuses.map(weaponOptionText):['ไม่มี']){const line=document.createElement('div');line.textContent=text;options.append(line)}card.append(options);return card}
function equipEmblem(g){g=player.loot.gear.find(item=>item.id===g.id);if(!g||g.slot!=='emblem'||!WEAPON_NAMES[g.emblemWeapon])return false;player.loot.equipped.emblem=g.id;supportOnEquipmentChange();player.hp=Math.min(player.hp,maxHP());player.mp=Math.min(player.mp,maxMP());save();closeModal();if(!$('characterOverlay').hidden)renderCharacterWindow();updateUI();return true}
function unequipEmblem(){if(!player.loot.equipped.emblem)return false;delete player.loot.equipped.emblem;supportOnEquipmentChange();player.hp=Math.min(player.hp,maxHP());player.mp=Math.min(player.mp,maxMP());save();closeModal();if(!$('characterOverlay').hidden)renderCharacterWindow();updateUI();return true}
function showEmblemDialog(g){modal(g.name,emblemStatusCard(g),player.loot.equipped.emblem===g.id?[['ถอด Emblem',unequipEmblem,true]]:[['สวม Emblem',()=>equipEmblem(g),true]])}

